/*
 * A071539  Number of n-tuples of elements e_1,e_2,...,e_n in the symmetric
 *          group S_3 such that the subgroup generated by e_1,e_2,...,e_n is
 *          S_3.
 * https://oeis.org/A071539
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = 6^n - 3*2^n - 3^n + 3
 * Range:     u8 n <= 3, u16 n <= 6, u32 n <= 12, u64 n <= 23, u128 n <= 23,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

/* Compute base^exp for integer exp >= 0 using binary exponentiation. */
static seq_t pow_seq_t(seq_t base, idx_t exp) {
    seq_t result = 1;
    seq_t b = base;
    while (exp) {
        if (exp & 1) {
            result *= b;
        }
        b *= b;
        exp >>= 1;
    }
    return result;
}

seq_t a(idx_t n) {
    /* Compute 2^n, 3^n and 6^n. */
    seq_t pow2 = pow_seq_t(2, n);
    seq_t pow3 = pow_seq_t(3, n);
    seq_t pow6 = pow_seq_t(6, n);

    /* a(n) = 6^n + 3 - 3*2^n - 3^n */
    seq_t result = pow6 + 3;          /* add the constant first to avoid underflow */
    result -= pow2 * 3;               /* subtract 3*2^n */
    result -= pow3;                   /* subtract 3^n */

    return result;
}
